<span class="line"><span style="color:#C678DD;">from</span><span style="color:#ABB2BF;"> fastapi.security </span><span style="color:#C678DD;">import</span><span style="color:#ABB2BF;"> HTTPBearer, HTTPAuthorizationCredentials</span></span>
